### 2.3. Centralise secret loading in a tiny helper (`config.js`)

```javascript
// config.js
require('dotenv').config(); // still keep for local dev

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

/**
 * Load a secret from AWS Secrets Manager.
 * If the secret is not found (e.g. during local dev), fall back to process.env.
 *
 * @param {string} secretName - The name/ARN of the secret.
 * @param {string} envVar    - Name of the environment variable that may hold the same value.
 * @returns {Promise<string>} The secret value.
 */
async function loadSecret(secretName, envVar) {
  // 1️⃣  Prefer an env‑var – this works for CI pipelines that inject secrets directly.
  if (process.env[envVar]) {
    return process.env[envVar];
  }

  // 2️⃣  If we have AWS credentials (via IAM role, env, or shared config) try Secrets Manager.
  if (process.env.AWS_REGION) {
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);
      // Secrets Manager can return a JSON string or plain text.
      if (response.SecretString) {
        // If you store a JSON blob with many keys, you could parse it here.
        return response.SecretString;
      }
    } catch (err) {
      // Log only the fact a secret wasn't found – don't expose details.
      console.warn(`[config] Unable to fetch secret "${secretName}" from Secrets Manager: ${err.name}`);
    }
  }

  // 3️⃣  Final fallback – throw an explicit error so the app fails fast.
  throw new Error(`Missing required secret: ${envVar}`);
}

/**
 * Export a ready‑to‑use config object.
 * This Promise resolves once all async secret fetches finish.
 */
module.exports = (async () => {
  return {
    port: process.env.PORT || 3000,
    allowedOrigins: (process.env.ALLOWED_ORIGINS?.split(',')) ?? [],
    demoToken: await loadSecret('my-app/demo-token', 'DEMO_TOKEN'), // secret name can be ARN or friendly name
  };
})();
```

### 2.4. Update `app.js` to use the new config

```javascript
// app.js
const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// Load config *once* at startup (the exported value is a Promise)
const getConfig = require('./config');

(async () => {
  const cfg = await getConfig;   // { port, allowedOrigins, demoToken }

  // ------------------------------------------------------------
  // Security middleware (same as in the previous review)
  // ------------------------------------------------------------
  app.use(helmet());
  app.use(cors({ origin: cfg.allowedOrigins, methods:['GET','POST','PUT','DELETE'], credentials:true }));
  const apiLimiter = rateLimit({ windowMs:15*60*1000, max:100, standardHeaders:true, legacyHeaders:false });
  app.use('/api/', apiLimiter);
  app.use('/users', apiLimiter);
  app.use(express.json());

  // Logging
  const logger = winston.createLogger({
    level: 'info',
    format: winston.format.json(),
    transports: [
      new winston.transports.File({ filename:'logs/error.log', level:'error' }),
      new winston.transports.File({ filename:'logs/combined.log' }),
      new winston.transports.Console(),
    ],
  });
  app.use(morgan('combined', { stream:{ write:msg=>logger.info(msg.trim()) } }));

  // ------------------------------------------------------------
  // Auth middleware – uses the secret we fetched earlier
  // ------------------------------------------------------------
  function requireAuth(req, res, next) {
    const auth = req.headers.authorization;
    if (!auth || !auth.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing token' });
    }
    const token = auth.split(' ')[1];
    if (token !== cfg.demoToken) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    next();
  }

  // ------------------------------------------------------------
  // Routes
  // ------------------------------------------------------------
  app.get('/health', (req, res) => {
    res.json({ status:'ok', timestamp:new Date().toISOString() });
  });

