### 2.2. Harden the Express stack

```js
// app.js (refactored)
const express = require('express');
const helmet = require('helmet');                     // npm i helmet
const rateLimit = require('express-rate-limit');     // npm i express-rate-limit
const cors = require('cors');                         // npm i cors
const morgan = require('morgan');                     // npm i morgan
const { port } = require('./config');

const app = express();

// ----- Global security middleware -----
app.use(helmet());                     // Sets a strong set of HTTP security headers
app.use(cors({                         // Restrict origins to known clients (adjust as needed)
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json({ limit: '1mb' })); // Body parser with size limit

// Request logging (helps with detection & forensics)
app.use(morgan('combined'));

// Rate limiting – mitigate brute‑force, DoS, credential stuffing, etc.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----- Centralised error handling (avoid info leakage) -----
function errorHandler(err, req, res, next) {
  console.error(err); // keep a separate log file in production
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
}
```

### 2.3. Add authentication & role‑based access control (RBAC)

A simple JWT‑based approach is shown; replace with your preferred identity provider if needed.

```js
// auth.js (new file)
const jwt = require('jsonwebtoken');             // npm i jsonwebtoken
const secret = process.env.JWT_SECRET || 'change-me';

function generateToken(payload) {
  return jwt.sign(payload, secret, { expiresIn: '1h' });
}

function verifyToken(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, secret);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Optional role check helper
function requireRole(role) {
  return (req, res, next) => {
    if (req.user && req.user.role === role) return next();
    return res.status(403).json({ error: 'Forbidden' });
  };
}

module.exports = { generateToken, verifyToken, requireRole };
```

