const bcrypt = require('bcrypt'); // npm i bcrypt
const users = [
  // Passwords should be hashed ahead of time; this is just an example.
  { id: 1, name: 'Alice', email: 'alice@example.com', passwordHash: '$2b$10$...' , role: 'admin' },
];

app.post('/login', async (req, res, next) => {
  try {
