const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { celebrate, Joi, Segments, errors: celebrateErrors } = require('celebrate');
const bcrypt = require('bcrypt'); // for demo login, replace with real DB
const { port, corsOrigin } = require('./config');
const { generateToken, verifyToken, requireRole } = require('./auth');

const app = express();

// ---- Middleware -------------------------------------------------
app.use(helmet());
app.use(cors({ origin: corsOrigin }));
app.use(express.json({ limit: '1mb' }));
app.use(morgan('combined'));

const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(globalLimiter);

// ---- Dummy data (replace with real database) -------------------
const users = [
  {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    passwordHash: bcrypt.hashSync('SuperSecret123', 10), // example only
    role: 'admin',
  },
  {
    id: 2,
    name: 'Bob',
    email: 'bob@example.com',
    passwordHash: bcrypt.hashSync('Password456', 10),
    role: 'user',
  },
];

// ---- Routes -----------------------------------------------------

