      next(err);
    }
  },
);

app.get(
  '/users',
  verifyToken,
  requireRole('admin'),
  (req, res) => {
    // In production, paginate, filter, and never return password hashes.
    const safeUsers = users.map(({ passwordHash, ...rest }) => rest);
    res.json(safeUsers);
