## 3️⃣ Recommended migration to a **proper secrets manager**

Below are **concrete code snippets** for two popular cloud‑native secret stores. Choose the one that matches your platform (AWS, GCP, Azure, HashiCorp Vault, etc.).  

### 3.1 AWS – Parameter Store / Secrets Manager (Node SDK v3)

1. **Add dependencies**

   ```bash
   npm i @aws-sdk/client-ssm @aws-sdk/client-secrets-manager
   ```

2. **Create a tiny helper (`config/secrets.js`)**

   ```js
   // config/secrets.js
   const { SSMClient, GetParameterCommand } = require("@aws-sdk/client-ssm");
   const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

   const REGION = process.env.AWS_REGION || "us-east-1";
   const ssm = new SSMClient({ region: REGION });
   const secretsMgr = new SecretsManagerClient({ region: REGION });

   /**
    * Fetch a plain‑text Parameter Store value (SecureString)
    */
   async function getParam(name) {
     const cmd = new GetParameterCommand({ Name: name, WithDecryption: true });
     const { Parameter } = await ssm.send(cmd);
     return Parameter.Value;
   }

   /**
    * Fetch a secret from Secrets Manager (JSON string or binary)
    */
   async function getSecret(name) {
     const cmd = new GetSecretValueCommand({ SecretId: name });
     const { SecretString, SecretBinary } = await secretsMgr.send(cmd);
     return SecretString || Buffer.from(SecretBinary, "base64").toString("utf-8");
   }

   module.exports = { getParam, getSecret };
   ```

3. **Use the helper in `app.js` (or wherever you need the secret)**

   ```js
   const { getParam, getSecret } = require("./config/secrets");

   // Example: DB connection string from Parameter Store
   async function startServer() {
     const dbUrl = await getParam("/myapp/prod/DATABASE_URL");
     // use `dbUrl` to initialise your DB client …

     const stripeKey = await getSecret("myapp/stripe"); // returns raw secret string
     // initialise Stripe SDK: const stripe = require('stripe')(stripeKey);

     // now start Express
     const PORT = process.env.PORT || 3000;
     app.listen(PORT, () => console.log(`Server listening on ${PORT}`));
   }

   startServer().catch(err => {
     console.error("Failed to start server:", err);
     process.exit(1);
   });
   ```

4. **IAM Requirements** – Attach an IAM policy to the EC2/ECS task role (or Lambda execution role) that grants `ssm:GetParameter` and/or `secretsmanager:GetSecretValue` for the specific ARNs. No static keys in the repo.

---

### 3.2 HashiCorp Vault (Node client)

1. **Add dependency**

   ```bash
   npm i node-vault
   ```

2. **Create a Vault wrapper (`config/vault.js`)**

   ```js
   // config/vault.js
   const vault = require("node-vault")({
     apiVersion: "v1", // default
     endpoint: process.env.VAULT_ADDR || "https://vault.mycompany.com",
     token: process.env.VAULT_TOKEN, // preferably injected via the orchestrator, not a .env file
   });

   /**
    * Reads a secret at path `secret/data/<path>` (KV version 2)
    */
   async function readSecret(path) {
     const result = await vault.read(`secret/data/${path}`);
     // KV v2 returns { data: { data: {...} } }
     return result?.data?.data;
   }

   module.exports = { readSecret };
   ```

3. **Consume it**

   ```js
   const { readSecret } = require("./config/vault");

   async function startServer() {
     const { DATABASE_URL, STRIPE_SECRET_KEY } = await readSecret("myapp/prod");
     // use the values as you would with env vars
     // e.g. const stripe = require('stripe')(STRIPE_SECRET_KEY);
   }

   startServer().catch(err => {
     console.error("Vault error:", err);
     process.exit(1);
   });
   ```

4. **Runtime injection** – In Kubernetes you can use **Vault Agent Injector** or **Secret Init Containers** to mount the secret into the pod, removing the need for a hard‑coded `VAULT_TOKEN`.

