const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Request logging (combined format works well with most log aggregators)
app.use(morgan('combined'));

/* 4️⃣  Error handling helper -------------------------------------------------- */
function asyncHandler(fn) {
  return (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);
}

/* 5️⃣  Simple static “health” endpoint */
app.get(
  '/health',
  asyncHandler(async (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

/* 6️⃣  Authentication middleware (optional but strongly recommended) */
function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

/* 7️⃣  Protected "users" endpoint ------------------------------------------- */
app.get(
  '/users',
  authenticateJWT, // <‑‑ protect the endpoint
  asyncHandler(async (req, res) => {
    // In a real app, pull from DB, apply RBAC, etc.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    // Example of *minimal* data exposure – only return what’s needed
    const safeUsers = users.map(u => ({ id: u.id, name: u.name }));
    res.json(safeUsers);
  })
);

/* 8️⃣  Centralized error handler -------------------------------------------- */
app.use((err, req, res, next) => {
  console.error(err); // you may want a proper logger (winston, pino, etc.)
  const status = err.status || 500;
  const response = { error: err.message || 'Internal Server Error' };
  // Hide stack traces from the client in production
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

/* 9️⃣  Server start ----------------------------------------------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  // In production you’ll almost always be behind a reverse proxy (nginx, ALB, …)
  // Enable “trust proxy” so Express correctly handles X‑Forwarded‑Proto, etc.
  app.set('trust proxy', 1);
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});

/* Export for testing */
module.exports = app;
```

