#### 4.2 Load Secrets From a Managed Store at Runtime  

Below are three sample loaders you can **swap in** place of `require('dotenv').config();`. Each fetches secrets **just‑in‑time** and never writes them to disk.

---

##### a) **AWS Secrets Manager** (Node 12+)

```js
// secrets/aws.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Load a secret JSON (e.g., {"DATABASE_URL":"...","STRIPE_SECRET_KEY":"..."})
 * and assign each key to process.env.
 */
async function loadAwsSecrets(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  const secret = JSON.parse(response.SecretString);
  Object.assign(process.env, secret);
}

// Example usage (early in app startup)
await loadAwsSecrets('myapp/prod/secrets');
```

*Why this helps:*  
- Secrets are encrypted at rest & in transit.  
- IAM policies restrict which compute role can read them.  
- Rotation can be automated without code changes.

---

##### b) **HashiCorp Vault** (KV v2)

```js
// secrets/vault.js
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR || 'https://vault.mycompany.com',
  token: process.env.VAULT_TOKEN,          // injected via container/instance IAM
});

/**
 * Load a secret path (e.g., secret/data/myapp) and merge into process.env.
 */
async function loadVaultSecrets(path) {
  const { data: { data: secret } } = await vault.read(path);
  Object.assign(process.env, secret);
}

// Example usage
await loadVaultSecrets('secret/data/myapp');
```

*Why this helps:*  
- Centralised policy engine (ACLs).  
- Detailed audit logs for every secret read.  
- Supports dynamic secrets (e.g., temporary DB credentials).

---

##### c) **Google Secret Manager** (GCP)

```js
// secrets/gcp.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

/**
 * Fetch a secret version (e.g., "projects/myproj/secrets/DATABASE_URL/versions/latest")
 * and store it in process.env as the same key.
 */
async function loadGcpSecret(secretName) {
  const [accessResponse] = await client.accessSecretVersion({ name: secretName });
  const payload = accessResponse.payload.data.toString('utf8');
  const [key] = secretName.split('/').slice(-2, -1); // extracts "DATABASE_URL"
  process.env[key] = payload;
}

// Example usage (load a handful of known secrets)
await Promise.all([
  loadGcpSecret('projects/myproj/secrets/DATABASE_URL/versions/latest'),
  loadGcpSecret('projects/myproj/secrets/STRIPE_SECRET_KEY/versions/latest'),
]);
```

*Why this helps:*  
- Built‑in IAM integration with GCP service accounts.  
- Versioning & automatic rotation support.

---

#### 4.3 Unified Loader (plug‑and‑play)

You can create a tiny wrapper that decides **at runtime** which provider to use based on an environment variable:

```js
// secrets/index.js
async function loadSecrets() {
  const provider = process.env.SECRET_PROVIDER; // 'aws' | 'vault' | 'gcp' | 'env'
  switch (provider) {
    case 'aws':
      const { loadAwsSecrets } = require('./aws');
      await loadAwsSecrets(process.env.AWS_SECRET_NAME);
      break;
    case 'vault':
      const { loadVaultSecrets } = require('./vault');
      await loadVaultSecrets(process.env.VAULT_PATH);
      break;
    case 'gcp':
      const { loadGcpSecret } = require('./gcp');
      for (const name of process.env.GCP_SECRETS.split(',')) {
        await loadGcpSecret(name.trim());
      }
      break;
    case 'env':
    default:
      // Fallback to .env file (use only for local dev)
      require('dotenv').config({ path: process.env.ENV_PATH || '.env' });
  }
}

module.exports = { loadSecrets };
```

Then in `app.js` (or a `server.js` entry point) you early‑await it:

```js
(async () => {
  await require('./secrets').loadSecrets();  // <-- secrets are now in process.env
  const app = require('./app');               // actual Express app
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`Server listening on ${port}`));
})();
```

