## 3. Concrete Recommendations & Code Samples

Below is a **rewritten `app.js`** that addresses the above points while staying as close as possible to the original functionality.

```js
// -----------------------------------------------------------
// Secure Express Application
// -----------------------------------------------------------

require('dotenv').config();               // Load environment variables early
const express = require('express');
const helmet = require('helmet');         // Security headers
const cors = require('cors');             // Controlled cross‑origin requests
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // HTTP request logging
const { body, param, query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');     // Example JWT auth (install jsonwebtoken)
const app = express();

// -----------------------------------------------------------
// 1. General Security Hardening
// -----------------------------------------------------------

// Hide Express signature
app.disable('x-powered-by');

// Helmet adds a robust set of HTTP headers (CSP, HSTS, etc.)
app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        // adjust as needed for fonts, scripts, etc.
      },
    },
    referrerPolicy: { policy: 'no-referrer' },
    // other helmet options can be customized here
  })
);

// CORS – allow only trusted origins (adjust the array to your domains)
const allowedOrigins = [process.env.FRONTEND_ORIGIN || 'http://localhost:3000'];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow requests with no origin (like mobile apps, curl) – optional
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) {
        return callback(null, true);
      }
      return callback(new Error('Not allowed by CORS'));
    },
    credentials: true,
  })
);

// Rate limiting – basic DoS mitigation
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parser (JSON) + size limit to avoid payload attacks
app.use(express.json({ limit: '100kb' })); // adjust limit as required

// HTTP request logging (console for dev, can pipe to file/ELK in prod)
app.use(
  morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev')
);

// -----------------------------------------------------------
// 2. Simple Authentication Middleware (JWT example)
// -----------------------------------------------------------

const authMiddleware = (req, res, next) => {
  // Public routes (health) are exempt
  if (req.path === '/health') return next();

  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    // `JWT_SECRET` must be a long, random string kept out of source control
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // Attach user info to request
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

app.use(authMiddleware);

// -----------------------------------------------------------
// 3. Input Validation (example for future query params)
// -----------------------------------------------------------

const validateUserId = [
  param('id')
    .isInt({ gt: 0 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
];

// -----------------------------------------------------------
// 4. Routes
// -----------------------------------------------------------

app.get('/health', (req, res) => {
  // No auth required – health checks are typically unauthenticated
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: GET /users?limit=10
app.get(
  '/users',
  // Validate optional `limit` query param
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100')
    .toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app this would be a DB call with proper pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const limit = req.query.limit || users.length;
    res.json(users.slice(0, limit));
  }
);

// -----------------------------------------------------------
// 5. Centralised Error Handling (no stack traces in prod)
// -----------------------------------------------------------

app.use((err, req, res, next) => {
  // Log the full error for developers
  console.error(err);

  // Do not leak internal details to clients
  const response = {
    error: err.message || 'Internal Server Error',
  };

  // In production hide stack trace completely
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// -----------------------------------------------------------
// 6. Server Startup
// -----------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;
```

