```

```js
// azureSecrets.js
const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');

const vaultName = process.env.AZURE_KEYVAULT_NAME;
const url = `https://${vaultName}.vault.azure.net`;
const credential = new DefaultAzureCredential();
const client = new SecretClient(url, credential);

async function loadSecret(secretName) {
  const secret = await client.getSecret(secretName);
  return secret.value;
}

// Example at startup
(async () => {
  try {
    process.env.DATABASE_URL = await loadSecret('DatabaseUrl');
    process.env.STRIPE_SECRET_KEY = await loadSecret('StripeSecretKey');
    // ... more secrets
  } catch (e) {
    console.error('Azure Key Vault secret load failure:', e);
    process.exit(1);
  }
})();
```

**IAM requirement:** The Azure Managed Identity (or Service Principal) used by the app must have `get` permission on the vault’s secrets.

