// app.js
// Secure version of the simple Express demo
// --------------------------------------------------
// IMPORTANT: Never commit real secrets. Use a .env file
// --------------------------------------------------

require('dotenv').config();               // <‑‑ load env vars
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { param, validationResult } = require('express-validator');

const app = express();

// -------------------- Global Middleware --------------------
app.use(helmet());                         // security headers
app.disable('x-powered-by');               // hide Express version

// CORS – restrict to trusted origins (adjust for your front‑end)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || '*', // e.g. "https://myapp.com"
    methods: ['GET', 'POST', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

// Rate limiting – 100 requests per 15‑minute window per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Structured request logging (stdout is fine for containers)
app.use(morgan('combined'));

// --------------------------------------------------
// Health endpoint – unchanged but with a tiny sanity check
// --------------------------------------------------
