 * In a real project replace this with JWT verification,
 * session check, or any strategy you need.
 */
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  const token = authHeader.split(' ')[1];
  // Dummy check – replace with real verification logic
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }
  next();
}

// Example: sanitize optional query param `fields` (comma‑separated)
// to let callers request only certain fields (useful for privacy).
app.get(
  '/users',
  requireAuth,
  // Validation chain – optional `fields` query param
  [
    // Accept only alphanumeric + commas, max length 100
    (req, res, next) => {
      if (!req.query.fields) return next();
      const isValid = /^[a-zA-Z0-9_,]+$/.test(req.query.fields) && req.query.fields.length <= 100;
      if (!isValid) {
        return res.status(400).json({ error: 'Invalid fields parameter' });
      }
      next();
    },
  ],
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // If the caller asks for a subset of fields, filter the objects
    if (req.query.fields) {
      const requested = req.query.fields.split(',').map(f => f.trim());
      const filtered = users.map(u => {
        const obj = {};
        requested.forEach(k => {
