    // (demonstration of data‑exposure mitigation)
    const safeUsers = users.map(({ email, ...rest }) => rest);
    return res.json(safeUsers);
  }
);

// --------------------------------------------------
// Centralised error handler (no stack traces in prod)
// --------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err); // always log internally
  const status = err.status || 500;
  const response = {
