  stream: {
    write: msg => winston.info(msg.trim())
  }
}));

// Central error handler (must be added after all routes)
app.use((err, req, res, next) => {
  winston.error(`${req.method} ${req.originalUrl} – ${err.message}`, { stack: err.stack });
