### 2️⃣ Pull secrets from **AWS Secrets Manager** (or an equivalent cloud secret store)

*Add a tiny async loader that fetches the required values before the server starts.*

```js
// secrets.js  (new file)
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Retrieves a secret JSON string from AWS Secrets Manager.
 * @param {string} secretId The ARN or name of the secret.
 * @returns {Promise<Object>} Parsed secret payload.
 */
async function getSecret(secretId) {
  const cmd = new GetSecretValueCommand({ SecretId: secretId });
  const response = await client.send(cmd);
  // Secrets can be stored as plain text or as a JSON document.
  if (response.SecretString) {
    try {
      return JSON.parse(response.SecretString);
    } catch (_) {
      // Not JSON → return as raw string wrapped in an object.
      return { value: response.SecretString };
    }
  }
  throw new Error(`Secret ${secretId} does not contain a string value`);
}

module.exports = { getSecret };
```

