// 1️⃣  Core dependencies
const express = require('express');
const helmet = require('helmet');               // security headers
const cors = require('cors');                   // CORS control
const rateLimit = require('express-rate-limit'); // DoS protection
const morgan = require('morgan');               // request logging
const { body, param, query, validationResult } = require('express-validator'); // input validation
const jwt = require('jsonwebtoken');            // simple JWT auth (example)

// ----------------------------------------------------
// 2️⃣  App creation & basic hardening
const app = express();

// Remove the default Express header that reveals the framework
app.disable('x-powered-by');

// Apply default security headers
app.use(helmet());

// Restrict CORS to known origins (adjust for your environment)
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://my‑trusted‑frontend.example.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));

// Basic request logging (combined format) – can be replaced with winston for JSON logs
