  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // apply only to the potentially sensitive endpoint

// ----------------------------------------------------
// 4️⃣  Simple JWT auth middleware (replace with your auth strategy)
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }
  const token = authHeader.split(' ')[1];
  try {
    // In production use a strong secret/key and verify alg, exp, etc.
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// ----------------------------------------------------
// 5️⃣  Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * - Only authenticated callers can retrieve user data.
 * - Example of future input validation (e.g., query parameters) shown.
 */
