  '/users',
  authMiddleware,
  // Example query validation (if you ever add filters like ?page=2)
  // query('page').optional().isInt({ min: 1 }).toInt(),
  (req, res) => {
    // Validate any query params before using them
    // const errors = validationResult(req);
    // if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    // In a real app you would fetch this from a DB and never hard‑code e‑mail addresses.
    const users = [
      { id: 1, name: 'Alice' /* email omitted for privacy */ },
      { id: 2, name: 'Bob'   /* email omitted for privacy */ },
    ];
    res.json(users);
  }
);

// ----------------------------------------------------
// 6️⃣  Global error handler (prevents stack traces leaking)
app.use((err, req, res, next) => {
  console.error(err); // optionally pipe to a monitoring service
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;
  res.status(status).json({ error: message });
});

// ----------------------------------------------------
