### 📂 `config.js` (drop‑in)

```js
/**
 * config.js – Centralised secrets loader
 *
 * Usage:
 *   const config = require('./config');
 *   const dbUrl = config.get('DATABASE_URL');
 *
 * The module first tries to read the variable from the OS environment
 * (so you can still override locally). If it is missing, it lazily
 * fetches the secret from the configured Secrets Manager.
 *
 * The implementation below is for AWS Secrets Manager but can be
 * swapped for Azure, GCP, or HashiCorp Vault with only a few lines
 * changed.
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// -----------------------------------------------------
// 1️⃣ Configuration – you can set these via environment or
//    CI variables; they are **not** secrets themselves.
const REGION = process.env.AWS_REGION || 'us-east-1';
const SECRET_NAME = process.env.APP_SECRETS_NAME || 'my-app/prod';

// -----------------------------------------------------
// 2️⃣ Singleton client (re‑used for the life of the process)
const client = new SecretsManagerClient({ region: REGION });

// -----------------------------------------------------
// 3️⃣ In‑memory cache of secret key/value pairs
let secretCache = null;

// -----------------------------------------------------
// 4️⃣ Helper: fetch and parse the secret (expects JSON)
async function loadSecrets() {
  if (secretCache) return secretCache; // already loaded

  console.info('[config] fetching secrets from AWS Secrets Manager...');
  const command = new GetSecretValueCommand({ SecretId: SECRET_NAME });
  const response = await client.send(command);

  // Secrets Manager returns a string; we store them as a flat object.
  const payload = response.SecretString;
  try {
    secretCache = JSON.parse(payload);
    return secretCache;
  } catch (e) {
    throw new Error('Secret payload is not valid JSON – cannot initialise config');
  }
}

// -----------------------------------------------------
// 5️⃣ Public accessor – sync API (throws if secret not loaded)
function get(key) {
  // 5a) Prefer explicit OS env (useful for local dev)
  if (process.env[key]) return process.env[key];

  // 5b) If we already have the cache, return instantly
  if (secretCache && key in secretCache) return secretCache[key];

  // 5c) Otherwise we need to block until the secret is fetched.
  //     This is a *synchronous* façade – we turn the async load
  //     into a promise that is awaited once at startup.
  throw new Error(
    `Secret "${key}" not available. Ensure config.loadAll() is awaited during app bootstrap.`
  );
}

// -----------------------------------------------------
// 6️⃣ Bulk‑load helper – call once (e.g. in server start)
async function loadAll() {
  await loadSecrets();
}

// -----------------------------------------------------
// 7️⃣ Export the API
module.exports = {
  get,
  loadAll,
};
```

