```js
const logger = require('pino')();

function safeLogEnv(varName) {
  const val = process.env[varName];
  if (val) {
    logger.info({ [varName]: `${val.slice(0, 4)}***${val.slice(-4)}` }, `Loaded ${varName}`);
  }
}
safeLogEnv('DATABASE_URL');
```

